const expected = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const candidates = [
  "quarterly report 2026",
  "quarterly report _2026",
  "quarterly-report-_2026",
  "quarterly_report_2026",
  "quarterly_report_2026/",
  "quarterly-report-2026",
  "quarterly_report",
  "quarterly_report-2026",
  "quarterly-report_2026",
  "quarterly report_2026",
  "quarterly report 2026_",
  "quarterly_report_2026_0",
  "quarterly_report_2026_q1",
  "quarterly report _2026 ",
  "quarterly-report-2026-",
  "quarterly-report_2026",
];
for (const c of candidates) {
  const d = createHash("sha256").update(c, "utf8").digest("hex");
  if (d === expected) console.log("MATCH:", JSON.stringify(c));
}
console.log("done");
'

